PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS verification_jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,actor_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('QUEUED','CLAIMED','RUNNING','WAITING_RUNNER','COMPLETED','FAILED','CANCELLED')),attempt INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 5,available_at TEXT NOT NULL,claimed_by TEXT,claim_expires_at TEXT,last_heartbeat_at TEXT,error_code TEXT,error_message TEXT,request_key TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(run_id),UNIQUE(workspace_id,request_key));
CREATE INDEX IF NOT EXISTS verification_jobs_claim_idx ON verification_jobs(status,available_at,claim_expires_at);
CREATE TABLE IF NOT EXISTS runner_jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,verification_job_id TEXT NOT NULL REFERENCES verification_jobs(id) ON DELETE CASCADE,run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,check_id TEXT NOT NULL REFERENCES verification_checks(id) ON DELETE CASCADE,criterion_id TEXT NOT NULL,type TEXT NOT NULL,required_capability TEXT,payload_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('QUEUED','LEASED','RUNNING','COMPLETED','FAILED','CANCELLED','TIMED_OUT')),runner_id TEXT REFERENCES runner_registrations(id),lease_token_hash TEXT,lease_expires_at TEXT,attempt INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,available_at TEXT NOT NULL,result_json TEXT,error_json TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(verification_job_id,criterion_id));
CREATE INDEX IF NOT EXISTS runner_jobs_claim_idx ON runner_jobs(workspace_id,status,available_at,lease_expires_at);
CREATE INDEX IF NOT EXISTS runner_jobs_verification_idx ON runner_jobs(verification_job_id,created_at);
